CREATE TABLE users (
 id BIGSERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, dni VARCHAR(8) NOT NULL UNIQUE CHECK(dni ~ '^[0-9]{8}$'),
 email VARCHAR(150) NOT NULL UNIQUE, password VARCHAR(100) NOT NULL,
 role VARCHAR(12) NOT NULL CHECK(role IN ('PACIENTE','MEDICO','ADMIN')), active BOOLEAN NOT NULL DEFAULT true,
 facility VARCHAR(30) NOT NULL DEFAULT 'DEMO-001', coverage VARCHAR(20) NOT NULL DEFAULT 'VIGENTE' CHECK(coverage IN ('VIGENTE','VENCIDA','NO_VERIFICABLE')),
 coverage_until DATE NOT NULL DEFAULT (CURRENT_DATE + 365));
CREATE TABLE specialties (id BIGSERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, active BOOLEAN NOT NULL DEFAULT true, direct BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE doctors (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE REFERENCES users(id), specialty_id BIGINT NOT NULL REFERENCES specialties(id), active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE slots (id BIGSERIAL PRIMARY KEY, doctor_id BIGINT NOT NULL REFERENCES doctors(id), starts_at TIMESTAMPTZ NOT NULL, ends_at TIMESTAMPTZ NOT NULL, blocked BOOLEAN NOT NULL DEFAULT false, CHECK(ends_at > starts_at), UNIQUE(doctor_id, starts_at));
CREATE TABLE appointments (id BIGSERIAL PRIMARY KEY, patient_id BIGINT NOT NULL REFERENCES users(id), slot_id BIGINT NOT NULL REFERENCES slots(id), status VARCHAR(15) NOT NULL DEFAULT 'RESERVADA' CHECK(status IN ('RESERVADA','CANCELADA','ATENDIDA','NO_ASISTIO')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX unique_active_slot ON appointments(slot_id) WHERE status <> 'CANCELADA';
CREATE INDEX appointments_patient ON appointments(patient_id);
CREATE INDEX slots_date ON slots(starts_at);
CREATE TABLE audit (id BIGSERIAL PRIMARY KEY, appointment_id BIGINT REFERENCES appointments(id), actor_id BIGINT NOT NULL REFERENCES users(id), action VARCHAR(30) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
